import psycopg2, psycopg2.extras, os, json, base64, gzip
data = json.loads(gzip.decompress(base64.b64decode("")))
conn = psycopg2.connect(os.environ['DATABASE_URL'], cursor_factory=psycopg2.extras.RealDictCursor)
cur = conn.cursor()
imp = upd = skip = 0
for r in data:
    reg,exam,booked_by,bd,ed,rd,method,country,city,status,result,center,score,reval,reval_dt,reval_res,reval_sc,notes = r
    cur.execute("SELECT registration_number FROM plab_clients WHERE registration_number = %s", (reg,))
    if not cur.fetchone():
        skip += 1; continue
    bd_v = bd if bd else None
    cur.execute("SELECT id FROM ops_test_bookings WHERE registration_number = %s AND exam = %s AND booking_date = %s", (reg, exam, bd_v))
    ex = cur.fetchone()
    ed_v = ed if ed else None; rd_v = rd if rd else None; reval_dt_v = reval_dt if reval_dt else None
    if ex:
        cur.execute("UPDATE ops_test_bookings SET exam_type=%s, exam_date=%s, exam_status=%s, exam_result=%s, exam_result_date=%s, score=%s, test_center=%s, city_state=%s, country=%s, booked_by=%s, revaluation=%s, reval_applied_date=%s, reval_result=%s, reval_score=%s, notes=%s WHERE id=%s",
            (method, ed_v, status, result, rd_v, score, center, city, country, booked_by, reval, reval_dt_v, reval_res, reval_sc, notes, ex['id']))
        upd += 1
    else:
        cur.execute("INSERT INTO ops_test_bookings (registration_number, exam, exam_type, booking_date, exam_date, exam_status, exam_result, exam_result_date, score, test_center, city_state, country, booked_by, revaluation, reval_applied_date, reval_result, reval_score, notes, created_by) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)",
            (reg, exam, method, bd_v, ed_v, status, result, rd_v, score, center, city, country, booked_by, reval, reval_dt_v, reval_res, reval_sc, notes, 0))
        imp += 1
conn.commit()
print(f"Done: {imp} new, {upd} updated, {skip} skipped")
cur.execute("SELECT COUNT(*) as c FROM ops_test_bookings"); print("Total now:", cur.fetchone()['c'])
cur.execute("SELECT id, exam, booking_date, exam_date, exam_status, exam_result FROM ops_test_bookings WHERE registration_number = 'GCUKIP/25-26/016'")
for row in cur.fetchall(): print("Tribhushan:", dict(row))
conn.close()
